INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT2400000000000000000', '*', '', 'pub_doc24_pta_receipt', 'Reçu de contribution APEE (DOC-24)', 'other', 'A', '{CODE}-{AA}-{LETTRE}-{N6}', 1, 0, '["school_year","pupil_name","amount","payment_method","received_on","treasurer_name"]', '2026-10-23T13:03:00+01:00', '2026-10-23T13:03:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT24F0000000000000000', '*', '', 'pub_doc24_pta_receipt', 'fr', '<html><body><h1>{{establishment_name}}</h1><h2>Association des parents d''élèves et des enseignants (APEE)</h2><h2>Reçu de contribution volontaire</h2><p>Reçu de {{holder_name}} la somme de {{amount}} FCFA ({{payment_method}}) le {{received_on}}, au titre de l''année {{school_year}}, pour l''élève {{pupil_name}}.</p><p>La contribution à l''APEE est volontaire : elle n''a aucun effet sur l''inscription, la présence, les bulletins ni les documents de l''élève.</p><p>Le trésorier : {{treasurer_name}}</p><div>{{signature}}{{stamp}}</div><p>N° {{number}}</p><div class="qr">{{qr}}</div><p><small>Vérification : {{verification_url}}</small></p></body></html>', 1, '2026-10-23T13:03:00+01:00', NULL, '2026-10-23T13:03:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT24E0000000000000000', '*', '', 'pub_doc24_pta_receipt', 'en', '<html><body><h1>{{establishment_name}}</h1><h2>Parent-Teacher Association (PTA)</h2><h2>Voluntary contribution receipt</h2><p>Received from {{holder_name}} the sum of {{amount}} FCFA ({{payment_method}}) on {{received_on}}, for the year {{school_year}}, for the pupil {{pupil_name}}.</p><p>The PTA contribution is voluntary: it has no effect on the pupil''s enrolment, attendance, reports or documents.</p><p>Treasurer: {{treasurer_name}}</p><div>{{signature}}{{stamp}}</div><p>No. {{number}}</p><div class="qr">{{qr}}</div><p><small>Verification: {{verification_url}}</small></p></body></html>', 1, '2026-10-23T13:03:00+01:00', NULL, '2026-10-23T13:03:00+01:00');
INSERT INTO document_types (id, tenant_id, establishment_id, code, label, category, type_letter, number_template, qr_enabled, blockable, variables, created_at, updated_at) VALUES ('01PUBDT2500000000000000000', '*', '', 'pub_doc25_pta_statement', 'État financier de l''APEE (DOC-25)', 'other', 'E', '{CODE}-{AA}-{LETTRE}-{N6}', 0, 0, '["school_year","voted_line","statement_block","pending_line","balance_line"]', '2026-10-23T13:03:00+01:00', '2026-10-23T13:03:00+01:00');
INSERT INTO document_templates (id, tenant_id, establishment_id, type_code, locale, html, version, validated_at, created_by, created_at) VALUES ('01PUBDT25F0000000000000000', '*', '', 'pub_doc25_pta_statement', 'fr', '<html><body><style>pre{font-family:"DejaVu Sans Mono",monospace}pre{font-size:10px}</style><h1>{{establishment_name}}</h1><h2>État financier de l''APEE · {{school_year}}</h2><p>{{voted_line}}</p><pre>{{statement_block}}</pre><p>{{pending_line}}</p><p><strong>{{balance_line}}</strong></p><p>Signatures : le président et le trésorier de l''APEE.</p><p>Fait le {{issued_on}} · N° {{number}}</p></body></html>', 1, '2026-10-23T13:03:00+01:00', NULL, '2026-10-23T13:03:00+01:00');
